pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set block.timestamp to a known value
        vm.warp(100);
        // Initially pastBlockTime is 0 (default), so block.timestamp > 0
        vm.deal(address(this), 10 ether);
        // First call succeeds, sets pastBlockTime = 100
        (bool success1, ) = address(c).call{value: 10 ether}("");
        assertTrue(success1);
        // Now pastBlockTime = 100 (or 101 in buggy)
        // Warp to exactly the same timestamp
        vm.warp(100);
        // Second call: reference requires block.timestamp > pastBlockTime, which is false (100 > 100 false) -> reverts
        // Buggy: require(100 > pastBlockTime) -> if pastBlockTime is 100, same revert; but if buggy set it to 101, then 100 > 101 false -> also revert
        // Actually need a different approach: wait until pastBlockTime is set such that block.timestamp == pastBlockTime for reference but not for buggy
        // Simpler: after first call, reference sets pastBlockTime=100, buggy sets 101
        // Warp to 101: reference requires 101 > 100 true, executes; buggy requires 101 > 101 false -> reverts
        vm.warp(101);
        (bool success2, ) = address(c).call{value: 10 ether}("");
        // Reference succeeds (pastBlockTime becomes 101), buggy reverts (pastBlockTime stays 101 from first call? Actually buggy set it to 101 already)
        // Let's assert over pastBlockTime after first call
        // Reset
        c = new C();
        vm.warp(100);
        vm.deal(address(this), 10 ether);
        address(c).call{value: 10 ether}("");
        // Reference pastBlockTime = 100, buggy = 101
        // Assert that pastBlockTime is exactly 100 for reference (buggy would be 101)
        assertTrue(c.pastBlockTime() == 100);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set block number to a non-multiple of 15 (e.g., 1) so the condition triggers differently
        vm.roll(1);
        // Fund the test contract with 10 ether to send
        address alice = address(0x123);
        vm.deal(alice, 10 ether);
        // Send 10 ether via fallback
        vm.prank(alice);
        (bool success, ) = address(c).call{value: 10 ether}("");
        require(success, "fallback call failed");
        // After the call, the reference (condition == 0) would NOT transfer (balance stays 10 ether)
        // The buggy (condition != 0) WOULD transfer the balance to msg.sender (alice)
        // Assert that the contract's balance is still 10 ether (correct behavior: no transfer)
        assertTrue(address(c).balance == 10 ether, "Bug: balance was transferred when it should not have been");
    }
}
